// Provider simulator (dev only) — stands in for Meta WhatsApp Cloud API.
// Returns the REAL response shape (contacts + messages[0].id = wamid), not a
// convenient flat {external_ref}. That is the point of the simulator: a green mock
// run must exercise the same parsing the live provider will need. The old flat
// shape hid the fact that the dispatcher never captured the wamid.
// HTTP 500 when PROVIDER_MOCK_FAIL=true, so the real error path is exercised.
const body = $input.first().json.body || {};
const meta = body.metadata || {};
const channel = 'whatsapp';
// The dispatcher no longer sends a non-standard `metadata` object to WhatsApp
// (Meta would not know it); the request code travels in biz_opaque_callback_data.
const requestCode = body.biz_opaque_callback_data || meta.request_code || 'unknown';
// Real wamids look like 'wamid.HBgNMjM0ODA3NzY2NTU0FQIAEhgg...'. Keeping the
// request code inside the mock id makes execution logs readable and lets the
// legacy REQ-… fallback in 07 keep working during dev.
const wamid = 'wamid.mock-whatsapp-' + requestCode;
const fail = ['1', 'true', 'yes', 'on'].includes(String($env.PROVIDER_MOCK_FAIL || '').toLowerCase());

if (fail) {
  return [{ json: { http_code: 500, body: {
    error: 'SIMULATED_PROVIDER_FAILURE',
    detail: 'PROVIDER_MOCK_FAIL=true — the simulator rejected this request on purpose.',
    channel,
  } } }];
}

const digits = String(body.to || '').replace(new RegExp('[^0-9]', 'g'), '');
return [{ json: { http_code: 200, body: {
  messaging_product: 'whatsapp',
  contacts: [{ input: String(body.to || ''), wa_id: digits }],
  messages: [{ id: wamid, message_status: 'accepted' }],
  mock: true,
  note: 'SIMULATED — no real message was sent',
} } }];

// Provider simulator (dev only) — stands in for VoiceBip SMS.
// Returns a realistic success payload, or an HTTP 500 when PROVIDER_MOCK_FAIL=true
// so the dispatcher's real error path (onError -> failure log) is exercised.
const body = $input.first().json.body || {};
const meta = body.metadata || {};
const channel = 'sms';
const ref = 'mock-' + channel + '-' + (meta.request_code || body.to || 'unknown');
const fail = ['1', 'true', 'yes', 'on'].includes(String($env.PROVIDER_MOCK_FAIL || '').toLowerCase());

if (fail) {
  return [{ json: { http_code: 500, body: {
    error: 'SIMULATED_PROVIDER_FAILURE',
    detail: 'PROVIDER_MOCK_FAIL=true — the simulator rejected this request on purpose.',
    channel,
  } } }];
}

return [{ json: { http_code: 200, body: {
  mock: true,
  ok: true,
  channel,
  external_ref: ref,
  message_id: ref,
  status: 'sent',
  note: 'SIMULATED — no real message/call was sent',
} } }];

